INSERT INTO bang_tin (av,author,role,time,pinned,tag_cls,tag_txt,title,body,likes,cmt) VALUES ('QĐ','Quản Đức Anh','Manager','2 giờ trước',1,'tag--report','📊 Báo cáo tháng','KPI tháng 7: HT HOME đạt 105% target','Chúc mừng cả team! Doanh thu tháng 7 đạt 487tr (target 465tr), vượt 105% kế hoạch. Đóng góp lớn nhất từ khu Gò Vấp và Bình Thạnh. Chi tiết báo cáo đã gửi qua email, mọi người xem và chuẩn bị cho mục tiêu tháng 8 nhé.',14,5);
INSERT INTO bang_tin (av,author,role,time,pinned,tag_cls,tag_txt,title,body,likes,cmt) VALUES ('TB','Trần Đình Bảo','Admin','5 giờ trước',0,'tag--congrat','🎉 Chúc mừng','Chị Thu Hà lên Sale cấp 1','Xin chúc mừng chị Thu Hà chính thức thăng cấp Sale cấp 1 với 18 deal chốt trong tháng 7! Một cột mốc xứng đáng cho sự nỗ lực bền bỉ. Cả nhà cùng vào chúc mừng chị nào 👏',22,11);
INSERT INTO bang_tin (av,author,role,time,pinned,tag_cls,tag_txt,title,body,likes,cmt) VALUES ('TB','Trần Đình Bảo','Admin','Hôm qua',0,'tag--system','🔧 Cập nhật hệ thống','Cập nhật quy trình upload HĐ','Từ 15/07, tất cả deal cần upload đủ 3 trang HĐ (trang thông tin, trang điều khoản, trang ký) trước khi chuyển sang trạng thái "Đã chốt". Deal thiếu ảnh sẽ không được tính hoa hồng. Mọi người lưu ý cập nhật các deal đang mở.',9,3);
INSERT INTO bang_tin (av,author,role,time,pinned,tag_cls,tag_txt,title,body,likes,cmt) VALUES ('QĐ','Quản Đức Anh','Manager','2 ngày trước',0,'tag--meeting','📅 Meeting','Họp tổng kết tháng','Lịch họp tổng kết tháng 7 & triển khai mục tiêu tháng 8: 9h00 thứ Hai (05/08) tại phòng họp tầng 3. Nội dung: review KPI từng khu, phân bổ quỹ phòng mới, chốt chính sách hoa hồng Q3. Đề nghị cả team có mặt đầy đủ và đúng giờ.',7,4);
